// counter.js
console.log('counter evaluating');
let n = 0;
module.exports = { inc: () => ++n, get: () => n };

// app.js
const a = require('./counter');
const b = require('./counter');
a.inc(); a.inc(); b.inc();
console.log(a === b, a.get(), b.get());

How many times does 'counter evaluating' print? What does the last line log?

